import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.BZO4qERu.js";const E=JSON.parse('{"title":"配置参考","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/configuration.md","filePath":"zh/reference/configuration.md","lastUpdated":1793111003000}'),i={name:"zh/reference/configuration.md"};function o(r,e,h,n,p,l){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="配置参考" tabindex="-1">配置参考 <a class="header-anchor" href="#配置参考" aria-label="Permalink to &quot;配置参考&quot;">​</a></h1><p>配置分为部署默认值、当前检索表单和任务保存的不可变配置。修改今天的表单，不会改变已有任务。</p><h2 id="社区版环境变量" tabindex="-1">社区版环境变量 <a class="header-anchor" href="#社区版环境变量" aria-label="Permalink to &quot;社区版环境变量&quot;">​</a></h2><p>部署模板见仓库的 <a href="https://github.com/paperseek/paperseek/blob/main/.env.example" target="_blank" rel="noreferrer">.env.example</a>。</p><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>PAPERSEEK_DATABASE</code></td><td>SQLite 路径，默认 <code>~/.paperseek/paperseek.db</code></td></tr><tr><td><code>PAPERSEEK_LLM_API_TYPE</code></td><td><code>openai_responses</code>、<code>openai_chat</code> 或 <code>anthropic_messages</code></td></tr><tr><td><code>PAPERSEEK_LLM_BASE_URL</code></td><td>模型提供方 API 基础地址</td></tr><tr><td><code>PAPERSEEK_LLM_MODEL</code></td><td>对应提供方支持的模型 ID</td></tr><tr><td><code>PAPERSEEK_LLM_API_KEY</code></td><td>模型凭据</td></tr><tr><td><code>PAPERSEEK_OPENALEX_API_KEY</code></td><td>OpenAlex Key 或 Key 池</td></tr><tr><td><code>PAPERSEEK_SEMANTIC_SCHOLAR_API_KEY</code></td><td>可选的 Semantic Scholar Key</td></tr><tr><td><code>PAPERSEEK_PUBMED_API_KEY</code></td><td>可选的 NCBI Key</td></tr><tr><td><code>PAPERSEEK_WOS_API_KEY</code></td><td>Web of Science Starter Key</td></tr><tr><td><code>PAPERSEEK_WOS_DB</code></td><td>WoS 集合，例如 <code>WOS</code></td></tr><tr><td><code>PAPERSEEK_GOOGLE_SCHOLAR_API_KEY</code></td><td>Serper Key 或 Key 池</td></tr><tr><td><code>PAPERSEEK_WANFANG_API_KEY</code></td><td>万方数据 AppKey</td></tr><tr><td><code>PAPERSEEK_CONTACT_EMAIL</code></td><td>支持联系邮箱的数据源客户端使用的邮箱</td></tr><tr><td><code>PAPERSEEK_PROXY_URLS</code></td><td>HTTP(S) 代理池，每行一个或用逗号分隔；设置后取代设置页中保存的代理</td></tr><tr><td><code>PAPERSEEK_PROXY_SCOPE</code></td><td>哪些请求走代理：<code>models</code>、<code>ip_limited_sources</code>、<code>other_sources</code>，默认三项都走</td></tr><tr><td><code>PAPERSEEK_MAX_CONCURRENT_RUNS</code></td><td>同时运行的检索和综述任务数，默认 <code>4</code>，<code>0</code> 表示不限制</td></tr></tbody></table><p>直接运行 CLI 或服务时读取进程环境。Docker Compose 会加载可选 <code>.env</code>。仅复制模板不会配置直接启动的 Python 进程。</p><h3 id="powershell-示例" tabindex="-1">PowerShell 示例 <a class="header-anchor" href="#powershell-示例" aria-label="Permalink to &quot;PowerShell 示例&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_LLM_API_TYPE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;openai_chat&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_LLM_BASE_URL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://your-provider.example/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_LLM_MODEL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your-model-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_LLM_API_KEY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;your-key&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">paperseek serve</span></span></code></pre></div><p>请替换全部占位符。长期运行时优先使用操作系统或服务管理器的私有配置。上面的地址是示例，并非真实可调用的服务。</p><h3 id="openalex-与-serper-多-key" tabindex="-1">OpenAlex 与 Serper 多 Key <a class="header-anchor" href="#openalex-与-serper-多-key" aria-label="Permalink to &quot;OpenAlex 与 Serper 多 Key&quot;">​</a></h3><p>在对应环境变量或 Key 输入框中，用空白、逗号或分号分隔多个 Key。PaperSeek 会轮换请求的起始 Key，并区分鉴权失败与临时失败。</p><p>重复填写同一个 Key 不会增加可用容量；提供方自身的访问政策仍然适用。</p><h3 id="网络代理" tabindex="-1">网络代理 <a class="header-anchor" href="#网络代理" aria-label="Permalink to &quot;网络代理&quot;">​</a></h3><p>当你的网络无法直接访问模型或数据源，或者数据源对你的网络地址限速时，可以使用代理。在 <strong>设置 › 通用 › 网络代理</strong> 中填写；服务器部署也可以使用 <code>PAPERSEEK_PROXY_URLS</code>。环境变量优先，此时设置页中的代理只读。修改后需要重启服务端和 worker。</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_PROXY_URLS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://user:password@proxy-a.example:8080,http://user:password@proxy-b.example:8080&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAPERSEEK_PROXY_SCOPE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ip_limited_sources&quot;</span></span></code></pre></div><p>选择哪些请求通过代理发送：</p><table tabindex="0"><thead><tr><th>范围</th><th>包括</th><th>什么时候有用</th></tr></thead><tbody><tr><td><code>models</code></td><td>大模型、嵌入、重排和决策模型</td><td>无法直接访问模型服务时。本机和局域网地址始终直连。</td></tr><tr><td><code>ip_limited_sources</code></td><td>arXiv、Crossref、PaperHub、OpenReview、国家哲学社会科学学术期刊数据库、中华医学期刊库、期刊分区数据下载（ShowJCR 与北大核心、CSSCI 目录），以及未填写密钥的 PubMed 和 OpenAlex</td><td>这些数据源按网络地址计算请求次数。网络地址与他人共用或已被限速时，换一个出口会有帮助。</td></tr><tr><td><code>other_sources</code></td><td>Semantic Scholar、Web of Science、Google Scholar、万方数据，以及已填写密钥的数据源</td><td>这些数据源按密钥或共享额度计算，代理不会增加额度，只在无法直接访问时需要。</td></tr></tbody></table><p>未选中的请求按系统代理设置（<code>HTTPS_PROXY</code>、<code>NO_PROXY</code>）发送。填写多个代理时，请求（包括重试）会轮流使用它们。请求间隔、冷却时间和 <code>Retry-After</code> 对整个代理池统一生效，代理池发送请求的速度不会超过单个地址。</p><p>支持 HTTP 和 HTTPS 代理地址，<code>http://</code> 代理也能通过隧道访问 HTTPS。用户名和密码中的保留字符需要 URL 编码，参见 <a href="https://www.python-httpx.org/advanced/proxies/" target="_blank" rel="noreferrer">HTTPX 代理配置</a>。配置的代理不可用时不会退回直连，HTTP 407 表示代理鉴权失败。设置页中的连接测试也使用同一个代理。</p><p>在设置页保存的地址会在本机加密存储，之后不再显示，设置页只列出每个代理的主机和端口。<strong>设置 › 用户</strong> 中的 <strong>清空已保存的密钥</strong> 也会删除这些地址。不要提交真实代理凭据。</p><h3 id="并发任务" tabindex="-1">并发任务 <a class="header-anchor" href="#并发任务" aria-label="Permalink to &quot;并发任务&quot;">​</a></h3><p><code>PAPERSEEK_MAX_CONCURRENT_RUNS</code> 决定同时运行多少个检索和综述任务，其余任务排队等待。默认 <code>4</code>，<code>0</code> 表示不限制。无论该值多大，数据源和模型服务都有各自的限速，且由所有运行中的任务共享，所以调得更高主要会让每个任务等待更久。</p><h2 id="每次检索的设置" tabindex="-1">每次检索的设置 <a class="header-anchor" href="#每次检索的设置" aria-label="Permalink to &quot;每次检索的设置&quot;">​</a></h2><p>表单包含研究问题、来源、领域、预算、模型连接、初排序与来源专属选项。详见<a href="./../guide/search">检索</a>、<a href="./../guide/sources">数据源</a>和<a href="./../guide/models">模型</a>。</p><p>协议必须与地址匹配。实现 Chat Completions 的服务不一定支持 Responses 或 Anthropic Messages。OpenAI 兼容服务的基础地址通常以 <code>/v1</code> 结尾；基础地址输入框不要再拼接 <code>/chat/completions</code>。</p><h2 id="可选排序服务" tabindex="-1">可选排序服务 <a class="header-anchor" href="#可选排序服务" aria-label="Permalink to &quot;可选排序服务&quot;">​</a></h2><p>本地融合不需要外部初排序接口。在社区版或在线版自带密钥模式中使用 Embedding + Rerank、System One 时，需要填写相应连接。它们的 Key 与模型 ID 可以和主语言模型不同。</p><h2 id="在线版配置" tabindex="-1">在线版配置 <a class="header-anchor" href="#在线版配置" aria-label="Permalink to &quot;在线版配置&quot;">​</a></h2><p>PaperSeek 服务提供模型列表，连接由站点管理；自带密钥模式可配置通过服务器地址校验的公共接口。部署密钥、内部路由和允许列表属于运维设置，不是用户表单配置。</p><p>详见<a href="./../online/">在线版指南</a>。</p>`,30)])])}const k=t(i,[["render",o]]);export{E as __pageData,k as default};
